async function load() { try { const response = await fetch('/api/overview'); if(response.status === 401) { location.replace('/login.html'); return; } if (!response.ok) throw new Error('Unable to load data'); state = await response.json(); render(); } catch { $('#metrics').innerHTML = '<div class="empty">Unable to connect to the server. Please refresh.</div>'; } }

async function initialize() {
  try {
    const names = ["overview","vehicles","drivers","settings","trips","camera","road-conditions","detections","safety","sync","devices","reports"];
    await Promise.all(names.map(async name => { const response = await fetch(`/pages/${name}.html`); if (!response.ok) throw new Error("Page could not load"); document.getElementById(`${name}-page`).innerHTML = await response.text(); }));
document.addEventListener('click', event => { const button = event.target.closest('[data-event]'); if (button) openEvent(Number(button.dataset.event)); const trip = event.target.closest('[data-trip]'); if (trip) openTrip(trip.dataset.trip); });
$('#add-truck').addEventListener('click', openTruckForm); $('#truck-form').addEventListener('submit', saveTruck); $('#close-truck').addEventListener('click', () => $('#truck-dialog').close()); $('#cancel-truck').addEventListener('click', () => $('#truck-dialog').close());
$('#add-driver').addEventListener('click', () => openDriverForm()); $('#driver-form').addEventListener('submit', saveDriver); $('#driver-close').addEventListener('click', () => $('#driver-dialog').close()); $('#driver-cancel').addEventListener('click', () => $('#driver-dialog').close()); $('#driver-table').addEventListener('click', event => { const edit=event.target.closest('[data-edit-driver]'); const remove=event.target.closest('[data-remove-driver]'); if(edit) openDriverForm(edit.dataset.editDriver); if(remove) removeDriver(remove.dataset.removeDriver, remove); }); $('#display-name-form').addEventListener('submit', saveDisplayName);
$('#vehicle-table').addEventListener('click', event => { const remove = event.target.closest('[data-remove-truck]'); const action = event.target.closest('[data-vehicle-action]'); if (remove) removeTruck(remove.dataset.removeTruck, remove); else if (action) openVehicleDestination(action.dataset.truckId, action.dataset.vehicleAction); });
$('#vehicle-search').addEventListener('input', renderVehicles); $('#vehicle-view-cards').addEventListener('click', () => setVehicleView('cards')); $('#vehicle-view-table').addEventListener('click', () => setVehicleView('table'));
$('#truck-camera-grid').addEventListener('click', event => { const card = event.target.closest('[data-camera-truck]'); if (card) selectCameraTruck(card.dataset.cameraTruck); }); $('#clear-camera-selection').addEventListener('click', clearCameraSelection);
$('#camera-truck-selector').addEventListener('change', event => { if (event.target.value) selectCameraTruck(event.target.value); else clearCameraSelection(); });
$('#road-review-form').addEventListener('submit', saveRoadReview); $('#road-review-filter').addEventListener('change', renderRoadReviews); $('#road-review-list').addEventListener('click', event => { const button = event.target.closest('[data-road-review]'); if (button) openRoadReview(button.dataset.roadReview); }); $('#road-review-close').addEventListener('click', closeRoadReview); $('#road-review-outcome-form').addEventListener('submit', saveRoadOutcome); $('#road-review-dialog').addEventListener('close', () => { const video = $('#road-review-detail').querySelector('video'); if (video) { video.pause(); video.removeAttribute('src'); video.load(); } });
$('#road-condition-filter').addEventListener('change', renderRoadConditions);
$('#road-condition-list').addEventListener('click', event => { const button = event.target.closest('[data-condition-review]'); if (button) { location.hash = 'detections'; navigate(); openRoadReview(button.dataset.conditionReview); } });
$('#road-condition-add').addEventListener('click', () => { location.hash = 'detections'; navigate(); const form = document.querySelector('.road-review-add'); form.open = true; form.scrollIntoView({behavior:'smooth', block:'start'}); });
$('#overview-queue').addEventListener('click', event => { const button = event.target.closest('[data-queue-review]'); if (button) { location.hash = 'detections'; navigate(); openRoadReview(button.dataset.queueReview); } });
$('#start-camera').addEventListener('click', startCamera); $('#stop-camera').addEventListener('click', stopCamera);
$('#camera-device').addEventListener('change', changeCameraDevice); if (navigator.mediaDevices?.addEventListener) navigator.mediaDevices.addEventListener('devicechange', refreshCameraDevices); refreshCameraDevices();
$('#record-local-test').addEventListener('click', startLocalTestRecording); $('#stop-local-test').addEventListener('click', stopLocalTestRecording);
$('#auto-capture-start').addEventListener('click', startAutoCapture); $('#auto-capture-stop').addEventListener('click', stopAutoCapture);
$('#trip-search').addEventListener('input', renderTrips); $('#trip-vehicle-filter').addEventListener('change', renderTrips); $('#trip-driver-filter').addEventListener('change', renderTrips); $('#trip-date-filter').addEventListener('change', renderTrips); $('#trip-clear-filters').addEventListener('click', clearTripFilters); $('#trip-fuel-form').addEventListener('submit', saveTripFuel); $('#trip-efficiency').addEventListener('input', updateFuelPreview); $('#trip-price').addEventListener('input', updateFuelPreview); $('#close-trip').addEventListener('click', () => $('#trip-dialog').close()); $('#dismiss-trip').addEventListener('click', () => $('#trip-dialog').close());
$('#map-vehicle').addEventListener('change', renderOverview);
$('#map-camera-link').addEventListener('click', async event => { const truck = $('#map-vehicle').value; if (truck === 'all') clearCameraSelection(); else selectCameraTruck(truck); if (document.fullscreenElement === $('#fleet-map-card')) { event.preventDefault(); try { await document.exitFullscreen(); location.hash = 'camera'; } catch { $('#map-fullscreen-message').textContent = 'Exit full screen to open the camera monitor.'; } } });
$('#map-fullscreen').addEventListener('click', toggleMapFullscreen); document.addEventListener('fullscreenchange', updateMapFullscreen);
$('#google-map-form').addEventListener('submit', connectGoogleMap); $('#map-use-osm').addEventListener('click', useOpenStreetMap); $('#google-traffic').addEventListener('change', updateGoogleTraffic);
$('#assignment-truck').addEventListener('change', loadAssignmentForm); $('#assignment-form').addEventListener('submit', saveAssignment); $('#pick-destination').addEventListener('click', beginDestinationPick); $('#clear-destination').addEventListener('click', clearDestinationPick); $('#assignment-list').addEventListener('click', event => { const button = event.target.closest('[data-edit-assignment]'); if (button) editAssignment(button.dataset.editAssignment); });
$('#assignment-destination').addEventListener('input', suggestDestination); $('#assignment-destination').addEventListener('keydown', event => { if (event.key === 'Escape') clearDestinationSuggestions(); }); $('#destination-suggestions').addEventListener('click', event => { const button = event.target.closest('[data-destination-index]'); if (button) chooseDestinationSuggestion(Number(button.dataset.destinationIndex)); });
$('#place-search-form').addEventListener('submit', searchPlaces); $('#place-search-input').addEventListener('input', suggestPlaces); $('#place-search-results').addEventListener('click', event => { const button = event.target.closest('[data-place-index]'); if (button) choosePlace(Number(button.dataset.placeIndex), button.dataset.placeAction); });
window.addEventListener('hashchange', navigate);
$('#menu-button').addEventListener('click', () => $('#sidebar').classList.toggle('open'));
$('#close-dialog').addEventListener('click', () => $('#event-dialog').close()); $('#dismiss-dialog').addEventListener('click', () => $('#event-dialog').close());
$('#review-button').addEventListener('click', async () => { const button = $('#review-button'); button.disabled = true; try { const response = await authenticatedMutation(`/api/events/${selectedId}/review`, 'PATCH'); if (!response.ok) throw new Error(); const updated = await response.json(); const index = state.events.findIndex(e => e.id === updated.id); if (index >= 0) state.events[index] = updated; render(); $('#event-dialog').close(); $('#toast').textContent = 'Sample detection marked as reviewed for this session.'; $('#toast').classList.add('visible'); setTimeout(() => $('#toast').classList.remove('visible'), 3500); } catch { button.disabled = false; $('#toast').textContent = 'Could not update detection. Please try again.'; $('#toast').classList.add('visible'); setTimeout(() => $('#toast').classList.remove('visible'), 3500); } });
$('#logout').addEventListener('click', logout); await loadAccount(); initializeStudy(); navigate(); await load(); await loadRoadReviews(); renderStudy();

  } catch { document.querySelector(".content").insertAdjacentHTML("afterbegin", "<p class=\"load-error\">The dashboard could not load. Please refresh.</p>"); }
}
initialize();
